/// Name of a model id in a slot for a look race (race-specific entries win).
pub fn gear_name(slot: &str, race: u8, model: u16) -> Option<&'static str> {
    let si = SLOTS.iter().position(|s| *s == slot)? as u8;
    let mut any = None;
    for (s, r, m, name) in NAMES {
        if *s != si || *m != model {
            continue;
        }
        if *r == race {
            return Some(name);
        }
        if *r == 0 {
            any = Some(*name);
        }
    }
    any
}
